// KONTEXT: Kosten-Node des Automation Compliance Guide. Liest aus der fertigen Ausführung des Hauptworkflows die Tokens der KI-Node, rechnet sie in Euro um und baut die Zeile für usage_log. Fragetexte werden nicht gespeichert.
// BEISPIEL: 5.200 Eingabe- und 700 Ausgabe-Tokens bei gpt-4o-mini ergeben 0,0012 EUR, die Zeile heißt workflow = compliance-guide-main.

// ---------- ABSCHNITT 1: Konstanten ----------
// „Preise pro 1 Mio. Tokens in USD (Listenpreis von OpenAI, geprüft am PRICE_STAND).“
const PRICES_USD = { 'gpt-4o-mini': { in: 0.15, out: 0.60 }, 'gpt-4o': { in: 2.50, out: 10.00 } };
// „Stand der Preise.“
const PRICE_STAND = '2026-10-07';
// „EZB-Referenzkurs: 1 EUR = x USD (Stand 2026-09-15).“
const USD_PER_EUR = 1.1539;
// „Falls das Modell in der Ausführung nicht lesbar ist.“
const DEFAULT_MODEL = 'gpt-4o-mini';
// „Name der KI-Node im Hauptworkflow, aus der die Tokens kommen.“
const MODEL_NODE = 'OpenAI Chat Model';
// „So heißt der Hauptworkflow in usage_log.“
const WORKFLOW = 'compliance-guide-main';

// ---------- ABSCHNITT 2: Ausführung prüfen ----------
// „Die Ausführung kommt aus der vorigen Node.“
const ex = $input.first().json;
// „Ist sie noch nicht fertig, fehlen Tokens. Dann abbrechen mit einer klaren Meldung.“
if (!ex.finished && ex.status !== 'error') throw new Error('Ausführung ' + ex.id + ' ist noch nicht fertig (Status: ' + ex.status + ')');
// „Die Laufdaten aller Nodes.“
const runData = ex.data?.resultData?.runData ?? {};

// ---------- ABSCHNITT 3: Tokens zählen ----------
// „Zähler für Eingabe- und Ausgabe-Tokens.“
let prompt = 0, completion = 0;
// „Alle Aufrufe der KI-Node durchgehen (auch Wiederholungen).“
for (const run of runData[MODEL_NODE] ?? []) {
  for (const out of run.data?.ai_languageModel?.[0] ?? []) {
    // „Echte Zahlen der API, sonst die Schätzung von n8n (das Kurs-Gateway liefert nur Schätzungen).“
    const u = out.json?.tokenUsage ?? out.json?.tokenUsageEstimate ?? {};
    prompt += u.promptTokens ?? 0;
    completion += u.completionTokens ?? 0;
  }
}
// „Kein KI-Aufruf (z. B. ungültige Eingabe oder Limit erreicht): nichts zu buchen.“
if (prompt + completion === 0) return [];

// ---------- ABSCHNITT 4: Modell und Kosten ----------
// „Modell aus der Workflow-Version dieser Ausführung lesen.“
const modelNode = (ex.workflowData?.nodes ?? []).find(n => n.name === MODEL_NODE);
// „Das Feld kann ein Objekt oder ein Text sein.“
const m = modelNode?.parameters?.model;
// „Modellname, sonst der Standard.“
const model = (typeof m === 'object' ? m?.value : m) || DEFAULT_MODEL;
// „Preis des Modells, falls bekannt.“
const p = PRICES_USD[model];
// „Kosten in USD, dann in EUR.“
const costUsd = p ? (prompt * p.in + completion * p.out) / 1e6 : null;

// ---------- ABSCHNITT 5: Zeile ----------
// „Die Zeile für usage_log. Manuelle Tests aus dem Editor zählen als Test, Webhook-Aufrufe als echt.“
return [{ json: { created_at: ex.startedAt, workflow: WORKFLOW, execution_id: String(ex.id), model, prompt_tokens: prompt, completion_tokens: completion, total_tokens: prompt + completion, cost_eur: costUsd === null ? null : Number((costUsd / USD_PER_EUR).toFixed(6)), price_stand: PRICE_STAND, is_test: ex.mode !== 'webhook' } }];
